from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_reviewed_ellipse_standard import ellipse_graph
SUMMARY={'type':'dataTable','headers':['Element','x²/a²+y²/b²=1, a>b','x²/a²+y²/b²=1, a<b'],'rows':[['Relation','c²=a²−b²','c²=a²−b²'],['Focus','(±c,0)','(0,±c)'],['Directrices','x=±c/e²','y=±c/e²'],['Major axis','y=0','x=0'],['Vertices','(±a,0)','(0,±a)'],['Co-vertices','(0,±b)','(±b,0)'],['Centre','(0,0)','(0,0)'],['Eccentricity','e=c/a<1','e=c/a<1']]}
PAGES=[page('134_page_2.jpg',260,[heading('(vii) Point of Intersection of an ellipse and a line'),paragraph('The given line and ellipse:'),eq(r'y=mx+c','45'),eq(r'\frac{x^2}{a^2}+\frac{y^2}{b^2}=1','46'),paragraph('develop a system of nonlinear equations:'),eq(r'\frac{x^2}{a^2}+\frac{y^2}{b^2}=1,\quad y=mx+c','47'),paragraph('The solution set {x,y} exists only if the curves intersect. The set of intersection points can be found by solving the nonlinear system simultaneously. Use line (45) in ellipse (46) to obtain the quadratic equation in x:'),eq(r'\frac{x^2}{a^2}+\frac{(mx+c)^2}{b^2}=1'),eq(r'x^2(a^2m^2+b^2)+2a^2mcx+a^2(c^2-b^2)=0','48'),paragraph('Equation (48) gives x₁,x₂, which are used in line (45) to obtain y₁,y₂. The set {(x₁,y₁),(x₂,y₂)} is the set of intersections. The points are real, coincident or imaginary according as the roots are real, coincident or imaginary, or the discriminant of equation (48):'),eq(r'\mathrm{Disc}=4a^4m^2c^2-4(a^2m^2+b^2)(a^2)(c^2-b^2)>0,\quad\mathrm{real\ and\ different}'),eq(r'\mathrm{Disc}=4a^4m^2c^2-4(a^2m^2+b^2)(a^2)(c^2-b^2)=0,\quad\mathrm{real\ and\ coincident}'),eq(r'\mathrm{Disc}=4a^4m^2c^2-4(a^2m^2+b^2)(a^2)(c^2-b^2)<0,\quad\mathrm{imaginary}'),heading('Note'),paragraph('The angle between tangent to ellipse and normal is always a right angle.'),heading('Example 15'),paragraph('Find intersections of line 2x−y−2=0 and ellipse 4x²+9y²=36.'),heading('Solution'),eq(r'2x-y-2=0\quad\Rightarrow\quad y=2x-2','49'),eq(r'4x^2+9y^2=36','50'),paragraph('Use line (49) in ellipse (50) for x-coordinates:'),eq(r'4x^2+9(2x-2)^2=36'),eq(r'4x^2+9(4x^2+4-8x)-36=0'),eq(r'40x^2-72x=0\quad\Rightarrow\quad x=0,\quad x=\frac95'),note('Here c is the line intercept, not the ellipse focal distance used earlier. Since a,b>0, a²m²+b²>0 for every finite m, so this discriminant classification is valid even for m=0. Vertical lines x=d have intersections y=±b√(1−d²/a²), real for |d|≤a; x=±a are vertical tangents. A negative discriminant gives complex algebraic solutions and no real graph intersection.')]),
page('135_page_1.jpg',261,[paragraph('Use the x-coordinates in line (49) to obtain y: x=0,9/5 give y=−2,8/5. Thus the two intersections (0,−2),(9/5,8/5) are real and distant and line 2x−y−2=0 intersects ellipse (50) at those points.'),heading('(viii) The equation of a tangent line in slope-form'),paragraph('If m is the slope of the tangent line to ellipse:'),eq(r'\frac{x^2}{a^2}+\frac{y^2}{b^2}=1','51'),paragraph('then its equation has form:'),eq(r'y=mx+c','52'),paragraph('Use line (52) in ellipse (51) to obtain a quadratic equation:'),eq(r'\frac{x^2}{a^2}+\frac{(mx+c)^2}{b^2}=1'),eq(r'x^2(a^2m^2+b^2)+2a^2mcx+a^2(c^2-b^2)=0','53'),paragraph('For a tangent the roots coincide and the discriminant equals zero:'),eq(r'4a^4m^2c^2-4(a^2m^2+b^2)(a^2)(c^2-b^2)=0'),eq(r'a^2m^2c^2-(a^2m^2+b^2)(c^2-b^2)=0'),paragraph('Divide out by 4a².'),eq(r'a^2m^2c^2-a^2m^2c^2+a^2m^2b^2-b^2c^2+b^4=0'),eq(r'a^2m^2b^2-b^2c^2+b^4=0'),eq(r'-b^2c^2=-(a^2m^2b^2+b^4)'),eq(r'c^2=a^2m^2+b^2\quad\Rightarrow\quad c=\pm\sqrt{a^2m^2+b^2}','54'),paragraph('Equation (54) is the condition of tangency. Use c in line (52):'),eq(r'y=mx+c=mx\pm\sqrt{a^2m^2+b^2}','55'),heading('Note'),paragraph('The equation of any tangent to ellipse x²/a²+y²/b²=1 in slope form is:'),eq(r'y=mx\pm\sqrt{a^2m^2+b^2}','56'),paragraph('Condition of tangency: line y=mx+c touches the ellipse under:'),eq(r'c=\pm\sqrt{a^2m^2+b^2}','57'),note('The two signs give the two parallel tangents of each finite slope. The source word “distant” means distinct intersection points. Add x=±a for the two vertical tangents. These formulas use the x- and y-denominators a²,b² directly, so they also work when the major axis is vertical.')]),
page('135_page_2.jpg',262,[heading('Example 16'),paragraph('For what value of c will 2x−y+c=0 touch ellipse x²/3+y²/4=1? Use those values to find the tangent lines.'),heading('Solution'),paragraph('Through result (57):'),eq(r'c=\pm\sqrt{a^2m^2+b^2}=\pm\sqrt{3(2)^2+4}=\pm4'),paragraph('Here m=2 is the slope. The required lines through (56) are:'),eq(r'y=mx+c=2x\pm4,\quad m=2'),heading('(ix) The equation of a tangent line to ellipse at a point'),paragraph('The equation of a tangent at P(x₁,y₁) to x²/a²+y²/b²=1 is:'),eq(r'y-y_1=m_1(x-x_1)','58'),paragraph('The slope is found by differentiating with respect to x:'),eq(r'\frac{x^2}{a^2}+\frac{y^2}{b^2}=1'),eq(r'\frac{2x}{a^2}+\frac{2y}{b^2}\frac{dy}{dx}=0'),eq(r'\frac{dy}{dx}=-\frac{b^2x}{a^2y}'),eq(r'\left(\frac{dy}{dx}\right)_{(x_1,y_1)}=-\frac{b^2x_1}{a^2y_1}=m_1','59'),paragraph('Substitute (59) in (58):'),eq(r'y-y_1=m_1(x-x_1)'),eq(r'y-y_1=-\frac{b^2x_1}{a^2y_1}(x-x_1)'),eq(r'\frac{yy_1}{b^2}-\frac{y_1^2}{b^2}=-\frac{xx_1}{a^2}+\frac{x_1^2}{a^2}\quad\Rightarrow\quad\frac{xx_1}{a^2}+\frac{yy_1}{b^2}=\frac{x_1^2}{a^2}+\frac{y_1^2}{b^2}'),eq(r'\frac{xx_1}{a^2}+\frac{yy_1}{b^2}=1,\quad\frac{x_1^2}{a^2}+\frac{y_1^2}{b^2}=1\ \mathrm{at}\ (x_1,y_1)','60'),heading('Example 17'),paragraph('Find the tangent at P(3,12/5) to ellipse x²/25+y²/9=1.'),heading('Solution'),eq(r'\frac{xx_1}{a^2}+\frac{yy_1}{b^2}=1'),eq(r'\frac{x(3)}{25}+\frac{y(12/5)}9=1,\quad (x_1,y_1)=(3,12/5),\ a^2=25,\ b^2=9'),eq(r'\frac{3x}{25}+\frac{12y}{45}=1\quad\Rightarrow\quad27x+60y-225=0\quad\Rightarrow\quad9x+20y-75=0'),note('The slope derivation divides by y₁; the final point form is also valid when y₁=0 and gives a vertical tangent. It requires P to lie on the ellipse. A gradient argument gives the same line without dividing by either coordinate. For Example 16, contacts are (−3/2,1) on y=2x+4 and (3/2,−1) on y=2x−4.')]),
page('136_page_1.jpg',263,[heading('(x) The equation of a normal line to ellipse at a point'),paragraph('The normal at P(x₁,y₁) to x²/a²+y²/b²=1 has equation:'),eq(r'y-y_1=m_2(x-x_1)','61'),paragraph('Find the normal slope by differentiating the ellipse:'),eq(r'\frac{x^2}{a^2}+\frac{y^2}{b^2}=1'),eq(r'\frac{2x}{a^2}+\frac{2y}{b^2}\frac{dy}{dx}=0'),eq(r'\frac{dy}{dx}=-\frac{b^2x}{a^2y}'),eq(r'\left(\frac{dy}{dx}\right)_{(x_1,y_1)}=-\frac{b^2x_1}{a^2y_1}=m_1'),eq(r'm_2=-\frac1{m_1}=\frac{a^2y_1}{b^2x_1}','62'),paragraph('Substitute (62) in (61) to obtain the normal:'),eq(r'y-y_1=m_2(x-x_1)'),eq(r'y-y_1=\frac{a^2y_1}{b^2x_1}(x-x_1),\quad m_2=\frac{a^2y_1}{b^2x_1}'),eq(r'\frac{y-y_1}{y_1/b^2}=\frac{x-x_1}{x_1/a^2}','63'),heading('Summary of Standard Ellipses'),SUMMARY,ellipse_graph(15),ellipse_graph(16),heading('Example 18'),paragraph('Find the normal at P(3,12/5) to ellipse x²/25+y²/9=1.'),heading('Solution'),eq(r'\frac{x-x_1}{x_1/a^2}=\frac{y-y_1}{y_1/b^2},\quad(x_1,y_1)=(3,12/5),\ a^2=25,\ b^2=9'),eq(r'\frac{x-3}{3/25}=\frac{y-12/5}{(12/5)/9}'),eq(r'\frac{25(x-3)}3=\frac{3(5y-12)}4'),eq(r'100(x-3)=9(5y-12)\quad\Rightarrow\quad100x-300-45y+108=0\quad\Rightarrow\quad100x-45y-192=0'),note('For the second column of the source summary, denominators are a² under x² and b² under y² with a<b. Thus the correct focal relation there is c²=b²−a², vertices (0,±b), co-vertices (±a,0), eccentricity e=c/b and directrices y=±b²/c for c>0. Its printed c²=a²−b², vertices (0,±a), co-vertices (±b,0) and e=c/a are incorrect. The two native orientation diagrams instead use a consistently as the semimajor length. The circle c=0 has no finite directrices. To handle zero coordinates in the normal, use the division-free equation (x₁/a²)(y−y₁)−(y₁/b²)(x−x₁)=0. At (±a,0) the normal is y=0; at (0,±b) it is x=0.')])]
for v in PAGES:v.update(title='CONICS-II',visualStatus='Complete line-intersection/tangent/normal proofs and all source summary entries',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':(v['page']+9)//2,'side':'left' if v['page']%2 else 'right','reason':'All discriminant expansions, point coordinates and normal denominator order visually checked'})
EXAMPLES=[]
for n,q,steps,ans,start,end in [
('15','Find intersections of 2x−y−2=0 and 4x²+9y²=36.',['Rewrite the line as y=2x−2.','Substitute: 4x²+9(2x−2)²=36.','Expand and simplify: 40x²−72x=8x(5x−9)=0.','Thus x=0 or 9/5; corresponding y=−2 or 8/5.','The intersections are (0,−2) and (9/5,8/5).','Check the second point: 4·81/25+9·64/25=900/25=36, and 18/5−8/5−2=0; the first also satisfies both.'],'(0,−2),(9/5,8/5).',260,261),
('16','Find c so 2x−y+c=0 touches x²/3+y²/4=1, and give tangents.',['Rewrite y=2x+c, so m=2 and the x/y denominators are 3 and 4.','Use c²=3m²+4=3·4+4=16.','Thus c=±4 and the tangents are y=2x+4 and y=2x−4.','Substitute the plus line: x²/3+(2x+4)²/4=1 gives 4x²+12x+9=(2x+3)²=0.','Its contact is (−3/2,1). The minus line similarly gives (2x−3)²=0, contact (3/2,−1).','Both contacts satisfy the ellipse and both tangent slopes equal 2, confirming the two parallel tangents.'],'c=±4; y=2x±4, contacts (∓3/2,±1).',262,262),
('17','Find the tangent at (3,12/5) to x²/25+y²/9=1.',['Check the contact: 9/25+(144/25)/9=9/25+16/25=1.','Use xx₁/25+yy₁/9=1.','Substitute: 3x/25+12y/45=1.','Multiply by 75 to obtain 9x+20y−75=0.','The contact lies on this line: 27+48−75=0.','The ellipse slope −9x/(25y) at the contact is −9/20, matching the line slope.'],'Tangent 9x+20y−75=0.',262,262),
('18','Find the normal at (3,12/5) to x²/25+y²/9=1.',['Check 9/25+16/25=1, so the contact is on the ellipse.','The tangent slope is −9·3/(25·12/5)=−9/20.','The perpendicular normal slope is 20/9.','Use y−12/5=(20/9)(x−3).','Multiply by 45: 45y−108=100x−300, giving 100x−45y−192=0.','At (3,12/5), the line expression is 300−108−192=0. Its slope product with the tangent is (20/9)(−9/20)=−1.'],'Normal 100x−45y−192=0.',263,263)]:
 EXAMPLES.append({'num':n,'title':'Ellipse Intersections and Tangency','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':pg,'jpg':f'{(pg+9)//2:03d}_page_{1 if pg%2 else 2}.jpg','verification':'Complete source question and derivation checked'} for pg in range(start,end+1)]})
